
CREATE TABLE users (id UUID NOT NULL, username VARCHAR(64) NOT NULL, name VARCHAR(120) NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(16) NOT NULL, rooms JSONB NOT NULL, lang VARCHAR(8), active BOOLEAN NOT NULL, last_login_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_users PRIMARY KEY (id), CONSTRAINT uq_users_username UNIQUE (username));

CREATE TABLE home (id INTEGER NOT NULL, name VARCHAR(120) NOT NULL, lat FLOAT NOT NULL, lon FLOAT NOT NULL, timezone VARCHAR(64) NOT NULL, currency VARCHAR(8) NOT NULL, price_area VARCHAR(16) NOT NULL, setup_done BOOLEAN NOT NULL, settings JSONB NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_home PRIMARY KEY (id));

CREATE TABLE rooms (id VARCHAR(64) NOT NULL, name VARCHAR(120) NOT NULL, floor INTEGER NOT NULL, outdoor BOOLEAN NOT NULL, geom JSONB NOT NULL, sort INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_rooms PRIMARY KEY (id));

CREATE TABLE events (id BIGINT GENERATED BY DEFAULT AS IDENTITY, ts TIMESTAMP WITH TIME ZONE NOT NULL, type VARCHAR(64) NOT NULL, level VARCHAR(8) NOT NULL, params JSONB NOT NULL, actor VARCHAR(160) NOT NULL, device_id VARCHAR(128), flow_id VARCHAR(64), room_id VARCHAR(64), cause_id BIGINT, CONSTRAINT pk_events PRIMARY KEY (id), CONSTRAINT fk_events_cause_id_events FOREIGN KEY(cause_id) REFERENCES events (id) ON DELETE SET NULL);

CREATE INDEX ix_events_ts ON events (ts);

CREATE INDEX ix_events_device_ts ON events (device_id, ts);

CREATE INDEX ix_events_type ON events (type);

CREATE INDEX ix_events_flow_id ON events (flow_id);

CREATE TABLE notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY, key VARCHAR(160) NOT NULL, level VARCHAR(8) NOT NULL, type VARCHAR(64) NOT NULL, params JSONB NOT NULL, route VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, dismissed_at TIMESTAMP WITH TIME ZONE, CONSTRAINT pk_notifications PRIMARY KEY (id), CONSTRAINT uq_notifications_key UNIQUE (key));

CREATE TABLE scenes (id VARCHAR(64) NOT NULL, name VARCHAR(120) NOT NULL, icon VARCHAR(32) NOT NULL, actions JSONB NOT NULL, sort INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_scenes PRIMARY KEY (id));

CREATE TABLE flows (id VARCHAR(64) NOT NULL, name VARCHAR(160) NOT NULL, enabled BOOLEAN NOT NULL, mode VARCHAR(16) NOT NULL, graph JSONB NOT NULL, version INTEGER NOT NULL, last_run_at TIMESTAMP WITH TIME ZONE, last_result VARCHAR(16), runs INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_flows PRIMARY KEY (id));

CREATE TABLE extensions (id VARCHAR(128) NOT NULL, name VARCHAR(160) NOT NULL, version VARCHAR(32) NOT NULL, trust VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL, enabled BOOLEAN NOT NULL, manifest JSONB NOT NULL, settings JSONB NOT NULL, grants JSONB NOT NULL, error TEXT, restarts INTEGER NOT NULL, pid INTEGER, started_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_extensions PRIMARY KEY (id));

CREATE TABLE dashboards (id VARCHAR(64) NOT NULL, name VARCHAR(120) NOT NULL, widgets JSONB NOT NULL, sort INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_dashboards PRIMARY KEY (id));

CREATE TABLE backups (id UUID NOT NULL, kind VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL, size BIGINT NOT NULL, path VARCHAR(255) NOT NULL, note TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL, finished_at TIMESTAMP WITH TIME ZONE, CONSTRAINT pk_backups PRIMARY KEY (id));

CREATE TABLE api_tokens (id UUID NOT NULL, user_id UUID NOT NULL, name VARCHAR(120) NOT NULL, token_hash VARCHAR(64) NOT NULL, scope VARCHAR(16) NOT NULL, rooms JSONB NOT NULL, expires_at TIMESTAMP WITH TIME ZONE, last_used_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_api_tokens PRIMARY KEY (id), CONSTRAINT fk_api_tokens_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, CONSTRAINT uq_api_tokens_token_hash UNIQUE (token_hash));

CREATE INDEX ix_api_tokens_user_id ON api_tokens (user_id);

CREATE TABLE devices (id VARCHAR(128) NOT NULL, name VARCHAR(120) NOT NULL, room_id VARCHAR(64), source VARCHAR(16) NOT NULL, kind VARCHAR(24) NOT NULL, model VARCHAR(160) NOT NULL, vendor VARCHAR(80) NOT NULL, address VARCHAR(255) NOT NULL, ieee VARCHAR(32), ext_id VARCHAR(128), caps JSONB NOT NULL, state JSONB NOT NULL, attrs JSONB NOT NULL, available BOOLEAN NOT NULL, disabled BOOLEAN NOT NULL, last_seen TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_devices PRIMARY KEY (id), CONSTRAINT fk_devices_room_id_rooms FOREIGN KEY(room_id) REFERENCES rooms (id) ON DELETE SET NULL, CONSTRAINT uq_devices_ieee UNIQUE (ieee));

CREATE INDEX ix_devices_ext_id ON devices (ext_id);

CREATE INDEX ix_devices_room_id ON devices (room_id);

CREATE TABLE flow_versions (id BIGINT GENERATED BY DEFAULT AS IDENTITY, flow_id VARCHAR(64) NOT NULL, version INTEGER NOT NULL, graph JSONB NOT NULL, author VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_flow_versions PRIMARY KEY (id), CONSTRAINT fk_flow_versions_flow_id_flows FOREIGN KEY(flow_id) REFERENCES flows (id) ON DELETE CASCADE);

CREATE INDEX ix_flow_versions_flow_id ON flow_versions (flow_id);

CREATE TABLE flow_runs (id UUID NOT NULL, flow_id VARCHAR(64) NOT NULL, status VARCHAR(16) NOT NULL, dry BOOLEAN NOT NULL, cause_id BIGINT, trace JSONB NOT NULL, ctx JSONB NOT NULL, started_at TIMESTAMP WITH TIME ZONE NOT NULL, finished_at TIMESTAMP WITH TIME ZONE, CONSTRAINT pk_flow_runs PRIMARY KEY (id), CONSTRAINT fk_flow_runs_flow_id_flows FOREIGN KEY(flow_id) REFERENCES flows (id) ON DELETE CASCADE);

CREATE INDEX ix_flow_runs_flow_started ON flow_runs (flow_id, started_at);

CREATE TABLE commands (id UUID NOT NULL, device_id VARCHAR(128) NOT NULL, values JSONB NOT NULL, status VARCHAR(16) NOT NULL, actor VARCHAR(160) NOT NULL, group_id VARCHAR(64), cause_id BIGINT, error TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL, done_at TIMESTAMP WITH TIME ZONE, CONSTRAINT pk_commands PRIMARY KEY (id), CONSTRAINT fk_commands_device_id_devices FOREIGN KEY(device_id) REFERENCES devices (id) ON DELETE CASCADE);

CREATE INDEX ix_commands_group_id ON commands (group_id);

CREATE INDEX ix_commands_device_id ON commands (device_id);

CREATE TABLE history (id BIGINT GENERATED BY DEFAULT AS IDENTITY, device_id VARCHAR(128) NOT NULL, cap VARCHAR(32) NOT NULL, ts TIMESTAMP WITH TIME ZONE NOT NULL, num FLOAT, txt VARCHAR(255), CONSTRAINT pk_history PRIMARY KEY (id), CONSTRAINT fk_history_device_id_devices FOREIGN KEY(device_id) REFERENCES devices (id) ON DELETE CASCADE);

CREATE INDEX ix_history_dev_cap_ts ON history (device_id, cap, ts);

CREATE TABLE stats (device_id VARCHAR(128) NOT NULL, cap VARCHAR(32) NOT NULL, hour TIMESTAMP WITH TIME ZONE NOT NULL, mean FLOAT NOT NULL, min FLOAT NOT NULL, max FLOAT NOT NULL, last FLOAT NOT NULL, n INTEGER NOT NULL, CONSTRAINT pk_stats PRIMARY KEY (device_id, cap, hour), CONSTRAINT fk_stats_device_id_devices FOREIGN KEY(device_id) REFERENCES devices (id) ON DELETE CASCADE);

